import{BOY,GIRL}from'./player-data.mjs';import{selectPlayerFrame}from'../gohyeon-pair/player-frame.mjs';import{data,foot}from'./view-data.mjs';
const brands=new WeakMap(),FETCH=globalThis.fetch?.bind(globalThis),BITMAP=globalThis.createImageBitmap?.bind(globalThis),DECODE=b=>BITMAP(new Blob([b])),BASE=new URL('../../',import.meta.url);
// Vite rewrites static directory URLs without their trailing slash. Preserve directory semantics.
BASE.pathname=BASE.pathname.replace(/\/?$/, '/');
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export const isAuthoritativeForestPlayer=p=>brands.get(p)?.()===true;
export async function prepareForestPlayer(options={}){if(!options||Object.getPrototypeOf(options)!==Object.prototype)throw Error('FOREST_PLAIN_OPTIONS');for(const k of Reflect.ownKeys(options)){const d=Object.getOwnPropertyDescriptor(options,k);if(!['appearance','signal','fetcher','decode'].includes(k)||!d?.enumerable||!Object.hasOwn(d,'value'))throw Error('FOREST_PLAYER_OPTIONS')}
 const{appearance='boy',signal,fetcher=FETCH,decode=DECODE}=options;if(!['boy','girl'].includes(appearance))throw Error('FOREST_PLAYER_APPEARANCE');let dead=false,pending;const images=new Map(),closed=new WeakSet(),check=()=>{if(dead||signal?.aborted)throw Error('FOREST_PLAYER_CLOSED')},close=im=>{if(im&&!closed.has(im)){closed.add(im);(()=>{try{im.close?.()}catch{}})()}},dispose=()=>{if(dead)return;dead=true;signal?.removeEventListener('abort',dispose);for(const im of images.values())close(im);images.clear()};if(signal!==undefined&&!(signal instanceof AbortSignal))throw Error('FOREST_SIGNAL');signal?.addEventListener('abort',dispose,{once:true});
 try{const pins=appearance==='boy'?BOY.frames.map(f=>({key:f.frame,path:'development/gohyeon-pair/player_frames/'+f.path,sha256:f.sha256,width:107,height:107})):[{key:'girl',path:GIRL.atlas.src,...GIRL.atlas}];for(const p of pins){check();const r=await fetcher(new URL(p.path,BASE),{signal});check();if(!r.ok)throw Error('FOREST_PLAYER_MISSING');const b=await r.arrayBuffer();check();if(await hash(b)!==p.sha256)throw Error('FOREST_PLAYER_PIN');pending=await decode(b);check();if(pending.width!==p.width||pending.height!==p.height)throw Error('FOREST_PLAYER_DIMENSIONS');images.set(p.key,pending);pending=null}
 const api=Object.freeze({appearance,draw(ctx,input){check();const v=data(input,['foot','facing','elapsedMs','moving']),xy=foot(v.foot),i=selectPlayerFrame({facing:v.facing,walking:v.moving,elapsedMs:v.elapsedMs});ctx.save();try{if(appearance==='boy')ctx.drawImage(images.get(i),xy[0]-53,xy[1]-90,107,107);else{const f=GIRL.frames['PLAYER_FEMALE.'+['FRONT','RIGHT','LEFT','BACK'][Math.floor(i/3)]+'.'+['IDLE','A','B'][i%3]],sc=80/192;ctx.imageSmoothingEnabled=false;ctx.drawImage(images.get('girl'),...f.rect,xy[0]-f.anchor[0]*sc,xy[1]-f.anchor[1]*sc,f.width*sc,f.height*sc)}check()}finally{ctx.restore()}return{appearance,frame:i,pivot:[53,90],drawBox:[107,107]}},dispose});if(fetcher===FETCH&&decode===DECODE&&BITMAP)brands.set(api,()=>!dead&&!signal?.aborted&&images.size>0);return api;
 }catch(e){close(pending);dispose();throw e}
}
